import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import type { ProjectEvent, ProjectSnapshot } from "../api/contract";

/** Shared contract fixtures generated by the runtime (runtime/api/fixtures). */
export function contractFixture<T>(name: string, schemaPrefix: string): T {
  const path = resolve(dirname(fileURLToPath(import.meta.url)), `../../../runtime/api/fixtures/${name}.json`);
  const f = JSON.parse(readFileSync(path, "utf8")) as { payloads: { schema: string; data: unknown }[] };
  const p = f.payloads.find((x) => x.schema.startsWith(schemaPrefix));
  if (!p) throw new Error(`fixture ${name} has no ${schemaPrefix}`);
  return structuredClone(p.data) as T;
}

/** F-ABC: A RUNNING, C RUNNING, B BLOCKED on A (05 §F-ABC). */
export function abcSnapshot(): ProjectSnapshot {
  return contractFixture<ProjectSnapshot>("abc-partial-block", "snapshot.schema.json");
}

export function event(prev: string, next: string, changes: ProjectEvent["payload"]["changes"], over: Partial<ProjectEvent> = {}): ProjectEvent {
  return {
    aggregate_id: "x",
    aggregate_type: "issue",
    aggregate_version: "1",
    event_id: `evt_${next}`,
    occurred_at: "2026-10-28T01:00:01Z",
    payload: { changes },
    previous_project_version: prev,
    project_id: "prj_fx001",
    project_version: next,
    recorded_at: "2026-10-28T01:00:01Z",
    schema_version: "1",
    seq: next,
    type: "issue.updated",
    ...over,
  };
}
